def reduce_compare(x, op_str, y):
    element_wise_result = eval("x " + op_str + " y")
    if op_str == "!=":
        return paddle.any(element_wise_result)
    elif (
        op_str == "is"
        or op_str == "is not"
        or op_str == "in"
        or op_str == "not in"
    ):
        return element_wise_result
    else:
        return paddle.all(element_wise_result)

